def the_readback(case, data):
    """RB — THE READBACK TABLE (THE LOOP's step 6 — the forms on file, no new form): sixty-four rows one per verse, graded against the kin's cells by CALL and the tape's lines by kind; the rows SUPPLIED with their writes; the one receipt behind; no pointer, state, open or stretch row; no retrograde row"""
    del P_[:]
    ask = case['ask']
    R = data['the_readback']['value']
    if ask == 'the_table':
        ink('19:1-21:23', 'sixty-four verses, %d rows; the grades %s' % (len(R), dict(collections.Counter(r['grade'] for r in R))))
        dat('the table a DATA row (the_readback); every row has kin — by CALL %d, on the tape %d' % (sum(1 for r in R if r['cell']), sum(1 for r in R if r['tape_kind'])))
        return out('the readback table (19:1-21:23) — %d rows one per verse, %s; every row graded against its kin' % (len(R), ', '.join('%s %d' % kv for kv in sorted(collections.Counter(r['grade'] for r in R).items()))), ['accepted'])
    if ask == 'the_supplied_rows':
        sup = [r['verses'] for r in R if r['grade'] == 'SUPPLIED']
        ink('19:1-21:23', 'the SUPPLIED rows %s — the thirteen lines\' first verses and the other laws with no seat before' % (sup,))
        dat('the thirteen lines\' first verses SUPPLIED with their writes (19:1, 19:4, 19:14, 19:15, 20:1, 20:10, 20:16, 20:19, 21:1, 21:10, 21:15, 21:18, 21:22) and the other holes (the way and the border, the three more, the plotting witness, the exemptions, the fearful, the captains, the tribute, the far cities, the measuring, the hands, the declaration, the atonement, the month, the seizing) — %d rows' % (len(sup),))
        return out('the supplied rows — %s: the code\'s holes compiled at the chapters\' own day' % (', '.join(sup),), ['accepted'])
    if ask == 'the_reference_rows':
        ref = [(r['verses'], r['tape_kind'], r['tape_verse']) for r in R if r['tape_kind']]
        ink('19:1, 19:2, 19:15, 19:20, 20:3, 20:10, 20:13-14, 20:17-18, 21:3, 21:15-17, 21:21-23', 'the reference rows %s' % (ref,))
        dat('the T1 rows against the tape\'s lines by kind and first verse — the nations cut off (12:29), the three cities set apart (4:41), the idolater\'s trial (17:2), the inciter\'s hear-and-fear (13:7), the shema (6:4), Sihon\'s messengers (Num 21:21), Midian\'s captives and officers (Num 31:9, 31:13), the seven devoted (7:1 — THE RECEIPT), the diviners (18:9), the heifer\'s statute (Num 19:1), Lamech\'s wives (Gen 4:19), Leah\'s womb (Gen 29:31), Joseph\'s portion (Gen 48:22), Peor\'s hanging (Num 25:4), Noah\'s blood (Gen 9:5) — %d rows, never a second act' % (len(ref),))
        return out('the reference rows — %d against the tape\'s lines (the nations, the cities, the trial, the inciter, the shema, Sihon, Midian, the seven, the diviners, the heifer, Lamech, Leah, Joseph, Peor, Noah): never a second write' % (len(ref),), ['accepted'])
    if ask == 'the_receipts':
        rc = data['the_receipts_behind']['value']
        ink('20:17, 19:8', '"as the LORD your God commanded you" and "as He swore to your fathers" — %s' % (rc,))
        dat('one receipt BEHIND — a run citation (Deuteronomy 7:1-5\'s line nations_devoted; the register\'s one seat in the three chapters, dispositioned at the tail); 19:8\'s oath formula a REFERENCE row without a register seat; no pointer row this sitting; 24:1 cited by the ink ahead at 21:14 a data row')
        return out('the receipts (20:17, 19:8) — one behind: 7:1-5\'s line nations_devoted, a run citation; the oath formula a reference; no pointer row', ['accepted'])
    if ask == 'no_state_no_open':
        ink('19:1-21:23', 'pointer rows %s, state rows %s, open rows %s, stretch rows %s' % ([r['verses'] for r in R if r['pointer']], [r['verses'] for r in R if r['state']], [r['verses'] for r in R if r['open']], [r['verses'] for r in R if r['stretch']]))
        dat('the forms on file, no new form — no pointer (the receipt behind), no state, no open (the disputes recorded with their arms), no stretch')
        return out('no pointer, no state, no open, no stretch row — the forms on file, no new form', ['accepted'])
    if ask == 'the_twin_diffed':
        ink('19:1-21:23', 'the twins diffed on the DB %s' % (TWIN,))
        dat('the reading\'s kin asserts read again (DJ4) — 19:1 with 12:29 eight, 19:4 with 4:42 nine, 19:9 with 11:22 ten, 19:20 with 13:12 seven, 20:5 with 20:6 eleven, 21:10 with 20:1 seven, 21:1 with 17:2 seven')
        return out('the twins diffed — 19:1 vs 12:29 %d, 19:4 vs 4:42 %d, 19:9 vs 11:22 %d, 19:20 vs 13:12 %d, 20:5 vs 20:6 %d, 21:10 vs 20:1 %d, 21:1 vs 17:2 %d: the reading\'s kin asserts read again' % (TWIN['19:1 vs 12:29'], TWIN['19:4 vs 4:42'], TWIN['19:9 vs 11:22'], TWIN['19:20 vs 13:12'], TWIN['20:5 vs 20:6'], TWIN['21:10 vs 20:1'], TWIN['21:1 vs 17:2']), ['accepted'])
    if ask == 'no_retrograde_row':
        ink('19:8, 20:1, 20:10', 'the oath formula, the exodus formula and Sihon\'s peace — REFERENCE rows against the tape\'s own lines; no narrative verb in the three chapters')
        dat('no retrograde marker, no stretch — the thirteen lines own-day at (40, 11, 1); the retellings never a second act')
        return out('no retrograde row — 19:8, 20:1 and 20:10 retell as REFERENCE rows; the thirteen lines own-day, no marker', ['accepted'])
    return 'no verdict in span', [], list(P_)
